-- =====================================================================================================================
-- Tutoiement (02/12/2026) : décision de la propriétaire — l'application tutoie partout le parent qui la lit.
-- Les textes envoyés par le serveur passent donc du « vous » au « tu » :
--   1. notifications in-app/push et messages d’erreur des fonctions SQL (communauté, messagerie privée, foyer,
--      missions, relais de nuit, stocks, rappels produits, « Se comprendre », espace nounou…) : la définition ACTUELLE
--      de chaque fonction (pg_get_functiondef) est relue en base et réappliquée avec ses seules chaînes changées ;
--   2. numéros d'urgence (description FR du 3114 et du 119) ;
--   3. contenus éditoriaux déjà semés : articles (titre, résumé, corps), recettes du catalogue v2 (conseils,
--      étapes, ingrédients), par remplacement PHRASE PAR PHRASE (replace) : un texte relu ou corrigé depuis l'administration
--      n'est touché que là où la phrase d'origine est encore présente mot pour mot.
-- Restent au « vous » : les pluriels réels (les deux parents, « vous deux », « l'un de vous »), les citations
-- (« … »), les titres de pages officielles et les questions que le parent adresse à une professionnelle.
-- Migration ADDITIVE et IDEMPOTENTE : aucune table ni colonne modifiée, rien de supprimé ; rejouée, elle ne change
-- plus rien (une phrase déjà convertie n'est plus trouvée). Les migrations déjà appliquées ne sont pas modifiées ;
-- les migrations pas encore appliquées (20261125, 20261127, 20261128) sont corrigées directement.
-- Sources alignées dans le même commit : src/i18n/<langue>, src/content, supabase/functions.
-- Retour arrière : sans objet pour le texte éditorial ; pour les fonctions, réappliquer leur définition précédente.
-- =====================================================================================================================

-- 1. Fonctions SQL (notifications et messages d'erreur)
do $mig$
declare
  r record; def text; newdef text; p record;
begin
  for r in select pr.oid from pg_proc pr join pg_namespace ns on ns.oid = pr.pronamespace
           where ns.nspname = 'public' and pr.prokind = 'f'
             and pr.prolang in (select oid from pg_language where lanname in ('plpgsql', 'sql')) loop
    def := pg_get_functiondef(r.oid);
    newdef := def;
    for p in select v.old_lit, v.new_lit from (values
    ($tu$'Publication anonyme : vous pouvez la signaler ou la masquer, mais pas bloquer son autrice (son identité reste protégée).'$tu$, $tu$'Publication anonyme : tu peux la signaler ou la masquer, mais pas bloquer son autrice (son identité reste protégée).'$tu$),
    ($tu$'Il ne respecte peut-être pas les règles de la communauté. Vous pouvez le retrouver dans votre profil communautaire.'$tu$, $tu$'Il ne respecte peut-être pas les règles de la communauté. Tu peux le retrouver dans ton profil communautaire.'$tu$),
    ($tu$'Seule la personne qui a demandé la mission la modifie ; vous pouvez proposer un autre moment.'$tu$, $tu$'Seule la personne qui a demandé la mission la modifie ; tu peux proposer un autre moment.'$tu$),
    ($tu$'Partage non autorisé : choisissez d''abord ce que vous voulez partager, et avec quel foyer.'$tu$, $tu$'Partage non autorisé : choisis d''abord ce que tu veux partager, et avec quel foyer.'$tu$),
    ($tu$'Activez d''abord le suivi de la vie sexuelle (facultatif) dans la confidentialité du cycle'$tu$, $tu$'Active d''abord le suivi de la vie sexuelle (facultatif) dans la confidentialité du cycle'$tu$),
    ($tu$'Retirez les informations personnelles (téléphone, adresse…) du nom ou de la description'$tu$, $tu$'Retire les informations personnelles (téléphone, adresse…) du nom ou de la description'$tu$),
    ($tu$'HOMI propose de prévoir le réapprovisionnement. Rien n’est créé sans votre accord.'$tu$, $tu$'HOMI propose de prévoir le réapprovisionnement. Rien n’est créé sans ton accord.'$tu$),
    ($tu$'Pas de photo dans une publication anonyme : elle pourrait révéler votre identité.'$tu$, $tu$'Pas de photo dans une publication anonyme : elle pourrait révéler ton identité.'$tu$),
    ($tu$'Attendez que ce membre accepte votre demande avant d''envoyer d''autres messages'$tu$, $tu$'Attends que ce membre accepte ta demande avant d''envoyer d''autres messages'$tu$),
    ($tu$'Choisissez un pseudonyme différent de votre prénom et de votre adresse e-mail'$tu$, $tu$'Choisis un pseudonyme différent de ton prénom et de ton adresse e-mail'$tu$),
    ($tu$'Une mission s''adresse à quelqu''un d''autre ; pour vous-même, notez une tâche.'$tu$, $tu$'Une mission s''adresse à quelqu''un d''autre ; pour toi-même, note une tâche.'$tu$),
    ($tu$'Un membre ne se remplace pas : retirez-le puis invitez la bonne personne.'$tu$, $tu$'Un membre ne se remplace pas : retire-le puis invite la bonne personne.'$tu$),
    ($tu$'Une demande traitée ne peut pas être rouverte : créez-en une nouvelle.'$tu$, $tu$'Une demande traitée ne peut pas être rouverte : crées-en une nouvelle.'$tu$),
    ($tu$'Une invitation a été acceptée. Confirmez l''accès avant tout partage.'$tu$, $tu$'Une invitation a été acceptée. Confirme l''accès avant tout partage.'$tu$),
    ($tu$'Ce message ne peut être envoyé qu''à l''autre adulte de votre foyer.'$tu$, $tu$'Ce message ne peut être envoyé qu''à l''autre adulte de ton foyer.'$tu$),
    ($tu$'Seul un de vos relais de nuit peut être proposé à l''échange.'$tu$, $tu$'Seul un de tes relais de nuit peut être proposé à l''échange.'$tu$),
    ($tu$'Dans une première demande, n''envoyez ni coordonnées ni liens'$tu$, $tu$'Dans une première demande, n''envoie ni coordonnées ni liens'$tu$),
    ($tu$'Si la mission est faite, vous pouvez la terminer dans HOMI.'$tu$, $tu$'Si la mission est faite, tu peux la terminer dans HOMI.'$tu$),
    ($tu$'Trop de messages en peu de temps, réessayez dans un instant'$tu$, $tu$'Trop de messages en peu de temps, réessaie dans un instant'$tu$),
    ($tu$'Votre partenaire souhaite partager quelque chose avec vous'$tu$, $tu$'Ton partenaire souhaite partager quelque chose avec toi'$tu$),
    ($tu$'Trop de publications en peu de temps, réessayez plus tard'$tu$, $tu$'Trop de publications en peu de temps, réessaie plus tard'$tu$),
    ($tu$'Trop de commentaires en peu de temps, réessayez plus tard'$tu$, $tu$'Trop de commentaires en peu de temps, réessaie plus tard'$tu$),
    ($tu$'Créez votre profil communautaire pour rejoindre un groupe'$tu$, $tu$'Crée ton profil communautaire pour rejoindre un groupe'$tu$),
    ($tu$'Créez votre profil communautaire pour rejoindre ce groupe'$tu$, $tu$'Crée ton profil communautaire pour rejoindre ce groupe'$tu$),
    ($tu$'Indiquez la quantité achetée (ou la nouvelle estimation).'$tu$, $tu$'Indique la quantité achetée (ou la nouvelle estimation).'$tu$),
    ($tu$'Trop de demandes de message aujourd''hui, réessayez demain'$tu$, $tu$'Trop de demandes de message aujourd''hui, réessaie demain'$tu$),
    ($tu$'Partage possible seulement avec un membre de votre foyer'$tu$, $tu$'Partage possible seulement avec un membre de ton foyer'$tu$),
    ($tu$'Acceptez ou refusez l’invitation : vous seul·e décidez.'$tu$, $tu$'Accepte ou refuse l’invitation : toi seul·e décides.'$tu$),
    ($tu$'Créez votre profil communautaire pour suivre un membre'$tu$, $tu$'Crée ton profil communautaire pour suivre un membre'$tu$),
    ($tu$'Vous n''avez pas l''autorisation de faire cette action.'$tu$, $tu$'Tu n''as pas l''autorisation de faire cette action.'$tu$),
    ($tu$'Vous avez créé ce groupe : supprimez-le ou gardez-le'$tu$, $tu$'Tu as créé ce groupe : supprime-le ou garde-le'$tu$),
    ($tu$'Vous ne pouvez pas répondre à votre propre demande.'$tu$, $tu$'Tu ne peux pas répondre à ta propre demande.'$tu$),
    ($tu$'Cinq liens actifs au plus : révoquez-en un d''abord.'$tu$, $tu$'Cinq liens actifs au plus : révoques-en un d''abord.'$tu$),
    ($tu$'Le commentaire auquel vous répondez est introuvable'$tu$, $tu$'Le commentaire auquel tu réponds est introuvable'$tu$),
    ($tu$'Vous ne pouvez pas modifier les stocks de ce foyer.'$tu$, $tu$'Tu ne peux pas modifier les stocks de ce foyer.'$tu$),
    ($tu$'Choisissez un pseudonyme avant d''écrire à un membre'$tu$, $tu$'Choisis un pseudonyme avant d''écrire à un membre'$tu$),
    ($tu$'Vous ne pouvez pas créer de mission dans ce foyer.'$tu$, $tu$'Tu ne peux pas créer de mission dans ce foyer.'$tu$),
    ($tu$'Votre compte communauté est suspendu jusqu''au %'$tu$, $tu$'Ton compte communauté est suspendu jusqu''au %'$tu$),
    ($tu$'Ouvrez HOMI pour répondre quand vous le pouvez.'$tu$, $tu$'Ouvre HOMI pour répondre quand tu le peux.'$tu$),
    ($tu$'Retirez les informations personnelles du choix'$tu$, $tu$'Retire les informations personnelles du choix'$tu$),
    ($tu$'Trop de messages aujourd''hui, réessayez demain'$tu$, $tu$'Trop de messages aujourd''hui, réessaie demain'$tu$),
    ($tu$'Vous pouvez la proposer à quelqu’un d’autre.'$tu$, $tu$'Tu peux la proposer à quelqu’un d’autre.'$tu$),
    ($tu$'Rappel (démonstration) dans votre foyer : '$tu$, $tu$'Rappel (démonstration) dans ton foyer : '$tu$),
    ($tu$' souhaite partager quelque chose avec vous'$tu$, $tu$' souhaite partager quelque chose avec toi'$tu$),
    ($tu$'Choisissez un pseudonyme avant de publier'$tu$, $tu$'Choisis un pseudonyme avant de publier'$tu$),
    ($tu$'Créez d''abord votre profil communautaire'$tu$, $tu$'Crée d''abord ton profil communautaire'$tu$),
    ($tu$'Ouvrez HOMI pour voir le moment proposé.'$tu$, $tu$'Ouvre HOMI pour voir le moment proposé.'$tu$),
    ($tu$'Des nuits de relais vous sont proposées'$tu$, $tu$'Des nuits de relais te sont proposées'$tu$),
    ($tu$'Ouvrez le planning pour les confirmer.'$tu$, $tu$'Ouvre le planning pour les confirmer.'$tu$),
    ($tu$'Vous êtes déjà inscrite à cet atelier'$tu$, $tu$'Tu es déjà inscrite à cet atelier'$tu$),
    ($tu$'Vous ne pouvez pas écrire à ce membre'$tu$, $tu$'Tu ne peux pas écrire à ce membre'$tu$),
    ($tu$'Vous avez déjà envoyé ce commentaire'$tu$, $tu$'Tu as déjà envoyé ce commentaire'$tu$),
    ($tu$' vous invite dans le groupe privé « '$tu$, $tu$' t’invite dans le groupe privé « '$tu$),
    ($tu$'Vous faites déjà partie de ce foyer.'$tu$, $tu$'Tu fais déjà partie de ce foyer.'$tu$),
    ($tu$'Ouvrez HOMI quand vous le souhaitez.'$tu$, $tu$'Ouvre HOMI quand tu le souhaites.'$tu$),
    ($tu$'Ouvrez l’application pour répondre.'$tu$, $tu$'Ouvre l’application pour répondre.'$tu$),
    ($tu$'Une nuit de relais vous est confiée'$tu$, $tu$'Une nuit de relais t’est confiée'$tu$),
    ($tu$'Rappel officiel dans votre foyer : '$tu$, $tu$'Rappel officiel dans ton foyer : '$tu$),
    ($tu$'Ouvrez l’application pour la voir.'$tu$, $tu$'Ouvre l’application pour la voir.'$tu$),
    ($tu$'Rejoignez ce groupe pour y publier'$tu$, $tu$'Rejoins ce groupe pour y publier'$tu$),
    ($tu$'Vous avez un nouveau message privé'$tu$, $tu$'Tu as un nouveau message privé'$tu$),
    ($tu$' suit maintenant vos publications'$tu$, $tu$' suit maintenant tes publications'$tu$),
    ($tu$'Rejoignez ce groupe pour répondre'$tu$, $tu$'Rejoins ce groupe pour répondre'$tu$),
    ($tu$'Vous avez déjà publié ce message'$tu$, $tu$'Tu as déjà publié ce message'$tu$),
    ($tu$'Vous avez déjà signalé ce membre'$tu$, $tu$'Tu as déjà signalé ce membre'$tu$),
    ($tu$'Créez votre profil communautaire'$tu$, $tu$'Crée ton profil communautaire'$tu$),
    ($tu$' partage un album avec vous : « '$tu$, $tu$' partage un album avec toi : « '$tu$),
    ($tu$'Choisissez un lieu public validé'$tu$, $tu$'Choisis un lieu public validé'$tu$),
    ($tu$'Ouvrez HOMI pour voir le détail.'$tu$, $tu$'Ouvre HOMI pour voir le détail.'$tu$),
    ($tu$'Vous avez une demande de message'$tu$, $tu$'Tu as une demande de message'$tu$),
    ($tu$'Vous devez avoir 18 ans ou plus'$tu$, $tu$'Tu dois avoir 18 ans ou plus'$tu$),
    ($tu$'Choisissez la nuit à échanger.'$tu$, $tu$'Choisis la nuit à échanger.'$tu$),
    ($tu$' a répondu à votre commentaire'$tu$, $tu$' a répondu à ton commentaire'$tu$),
    ($tu$'Rejoignez ce groupe pour voter'$tu$, $tu$'Rejoins ce groupe pour voter'$tu$),
    ($tu$' a commenté votre publication'$tu$, $tu$' a commenté ta publication'$tu$),
    ($tu$'Choisissez un moment à venir.'$tu$, $tu$'Choisis un moment à venir.'$tu$),
    ($tu$'Vous gardez déjà cet enfant.'$tu$, $tu$'Tu gardes déjà cet enfant.'$tu$),
    ($tu$'Une tâche vous est confiée'$tu$, $tu$'Une tâche t’est confiée'$tu$),
    ($tu$'Ouvrez HOMI pour répondre.'$tu$, $tu$'Ouvre HOMI pour répondre.'$tu$),
    ($tu$' a aimé votre publication'$tu$, $tu$' a aimé ta publication'$tu$),
    ($tu$' vous a mentionné·e'$tu$, $tu$' t’a mentionné·e'$tu$),
    ($tu$'Écrivez un message'$tu$, $tu$'Écris un message'$tu$),
    ($tu$'Votre publication'$tu$, $tu$'Ta publication'$tu$),
    ($tu$'Votre commentaire'$tu$, $tu$'Ton commentaire'$tu$),
    ($tu$'Votre partenaire'$tu$, $tu$'Ton partenaire'$tu$)
      ) as v(old_lit, new_lit) order by length(v.old_lit) desc loop
      newdef := replace(newdef, p.old_lit, p.new_lit);
    end loop;
    if newdef is distinct from def then
      execute newdef;
    end if;
  end loop;
end $mig$;

-- 2. Numéros d'urgence (France)
update public.emergency_resources set description = replace(description, 'Si vous pensez au suicide, si vous avez peur de vous faire du mal, ou si vous vous inquiétez pour un proche.', 'Si tu penses au suicide, si tu as peur de te faire du mal, ou si tu t’inquiètes pour un proche.') where country = 'FR' and phone = '3114';
update public.emergency_resources set description = replace(description, 'ou si vous avez peur de faire du mal à votre enfant.', 'ou si tu as peur de faire du mal à ton enfant.') where country = 'FR' and phone = '119';

