update public.articles set body_md = replace(replace(replace(replace(replace(replace(replace(body_md, $tu$Une consultation préconceptionnelle avec un médecin ou une sage-femme permet de faire le point sur votre santé, vos traitements et vos vaccinations, et de parler de la vitamine B9.$tu$, $tu$Une consultation préconceptionnelle avec un médecin ou une sage-femme permet de faire le point sur ta santé, tes traitements et tes vaccinations, et de parler de la vitamine B9.$tu$), $tu$- En cas de douleur intense du bas-ventre, de malaise ou de saignement abondant, appelez le 15 (ou le 112).$tu$, $tu$- En cas de douleur intense du bas-ventre, de malaise ou de saignement abondant, appelle le 15 (ou le 112).$tu$), $tu$Un calendrier se base sur vos cycles passés : il ne peut pas deviner un décalage à venir.$tu$, $tu$Un calendrier se base sur tes cycles passés : il ne peut pas deviner un décalage à venir.$tu$), $tu$- Si vous avez une maladie chronique ou un traitement au long cours.$tu$, $tu$- Si tu as une maladie chronique ou un traitement au long cours.$tu$), $tu$- Si vos cycles sont très irréguliers, absents, ou très douloureux.$tu$, $tu$- Si tes cycles sont très irréguliers, absents, ou très douloureux.$tu$), $tu$Non, elle propose une estimation à partir de vos cycles passés.$tu$, $tu$Non, elle propose une estimation à partir de tes cycles passés.$tu$), $tu$Votre calendrier en tient compte, sous forme d'estimation.$tu$, $tu$Ton calendrier en tient compte, sous forme d'estimation.$tu$) where slug = $tu$comprendre-fenetre-fertile$tu$;
